func filesWithRemainingAgentChanges(
	ctx context.Context,
	repo *git.Repository,
	shadowBranchName string,
	headCommit *object.Commit,
	filesTouched []string,
	committedFiles map[string]struct{},
	opts ...overlapOpts,
) []string {
	logCtx := logging.WithComponent(ctx, "checkpoint")

	// Use pre-resolved trees if provided, otherwise resolve from repo.
	var o overlapOpts
	if len(opts) > 0 {
		o = opts[0]
	}

	commitTree := o.headTree
	if commitTree == nil {
		var err error
		commitTree, err = headCommit.Tree()
		if err != nil {
			logging.Debug(logCtx, "filesWithRemainingAgentChanges: failed to get commit tree, falling back to file subtraction",
				slog.String("error", err.Error()),
			)
			return subtractFilesByName(ctx, filesTouched, committedFiles)
		}
	}

	shadowTree := o.shadowTree
	if shadowTree == nil {
		refName := plumbing.NewBranchReferenceName(shadowBranchName)
		shadowRef, err := repo.Reference(refName, true)
		if err != nil {
			logging.Debug(logCtx, "filesWithRemainingAgentChanges: shadow branch not found, falling back to file subtraction",
				slog.String("branch", shadowBranchName),
				slog.String("error", err.Error()),
			)
			return subtractFilesByName(ctx, filesTouched, committedFiles)
		}

		shadowCommit, err := repo.CommitObject(shadowRef.Hash())
		if err != nil {
			logging.Debug(logCtx, "filesWithRemainingAgentChanges: failed to get shadow commit, falling back to file subtraction",
				slog.String("error", err.Error()),
			)
			return subtractFilesByName(ctx, filesTouched, committedFiles)
		}

		shadowTree, err = shadowCommit.Tree()
		if err != nil {
			logging.Debug(logCtx, "filesWithRemainingAgentChanges: failed to get shadow tree, falling back to file subtraction",
				slog.String("error", err.Error()),
			)
			return subtractFilesByName(ctx, filesTouched, committedFiles)
		}
	}

	// Get worktree root for working tree checks when committed content
	// differs from shadow (distinguishes replacement from partial staging).
	var worktreeRoot string
	if wt, wtErr := repo.Worktree(); wtErr == nil {
		worktreeRoot = wt.Filesystem.Root()
	}

	var remaining []string

	for _, filePath := range filesTouched {
		// Skip files absent from the shadow tree — nothing to carry forward.
		// This covers two cases:
		//  1. Phantom paths: transcript mentions files the agent never created
		//     (e.g. agent writes src/types.go then creates src/types/types.go).
		//  2. Agent deletions: file was deleted on disk, so buildTreeWithChanges
		//     excluded it from the shadow tree. Carrying it forward would be a
		//     no-op since there's no content on disk to snapshot.
		// Without this check, phantom paths cause infinite carry-forward loops.
		shadowFile, err := shadowTree.File(filePath)
		if err != nil {
			logging.Debug(logCtx, "filesWithRemainingAgentChanges: file not in shadow tree, skipping",
				slog.String("file", filePath),
			)
			continue
		}

		// File wasn't committed at all — it has remaining changes
		if _, wasCommitted := committedFiles[filePath]; !wasCommitted {
			remaining = append(remaining, filePath)
			logging.Debug(logCtx, "filesWithRemainingAgentChanges: file not committed, keeping",
				slog.String("file", filePath),
			)
			continue
		}

		commitFile, err := commitTree.File(filePath)
		if err != nil {
			// File not in commit tree (deleted?) - keep it if it's in shadow
			remaining = append(remaining, filePath)
			logging.Debug(logCtx, "filesWithRemainingAgentChanges: file not in commit tree but in shadow, keeping",
				slog.String("file", filePath),
			)
			continue
		}

		if commitFile.Hash == shadowFile.Hash {
			logging.Debug(logCtx, "filesWithRemainingAgentChanges: content fully committed",
				slog.String("file", filePath),
			)
			continue
		}

		// Committed content differs from shadow. Check whether the working tree
		// still has changes — if clean, the user intentionally replaced the content
		// and there's nothing left to carry forward.
		if worktreeRoot != "" && workingTreeMatchesCommit(worktreeRoot, filePath, commitFile.Hash) {
			logging.Debug(logCtx, "filesWithRemainingAgentChanges: content differs from shadow but working tree is clean, skipping",
				slog.String("file", filePath),
				slog.String("commit_hash", commitFile.Hash.String()[:7]),
				slog.String("shadow_hash", shadowFile.Hash.String()[:7]),
			)
			continue
		}

		remaining = append(remaining, filePath)
		logging.Debug(logCtx, "filesWithRemainingAgentChanges: content mismatch with dirty working tree, keeping for carry-forward",
			slog.String("file", filePath),
			slog.String("commit_hash", commitFile.Hash.String()[:7]),
			slog.String("shadow_hash", shadowFile.Hash.String()[:7]),
		)
	}

	logging.Debug(logCtx, "filesWithRemainingAgentChanges: result",
		slog.Int("files_touched", len(filesTouched)),
		slog.Int("committed_files", len(committedFiles)),
		slog.Int("remaining_files", len(remaining)),
	)

	return remaining
}

var hasTranscriptFile bool
var transcriptBlobSize int64

if size, sizeErr := tree.Size(metadataDir + "/" + paths.TranscriptFileName); sizeErr == nil {
	hasTranscriptFile = true
	transcriptBlobSize = size
} else if size, sizeErr := tree.Size(metadataDir + "/" + paths.TranscriptFileNameLegacy); sizeErr == nil {
	hasTranscriptFile = true
	transcriptBlobSize = size
}

// If shadow branch exists but has no transcript (e.g., carry-forward from mid-session commit),
// check if the session has FilesTouched. Carry-forward sets FilesTouched with remaining files.
if !hasTranscriptFile {
	if len(state.FilesTouched) > 0 {
		// Shadow branch has files from carry-forward - check if staged files overlap
		// AND have matching content (content-aware check).
		if len(opts.stagedFiles) > 0 {
			// PrepareCommitMsg context: check staged files overlap with content
			result := stagedFilesOverlapWithContent(ctx, repo, tree, opts.stagedFiles, state.FilesTouched)
			logging.Debug(logCtx, "sessionHasNewContent: no transcript, carry-forward with staged files",
				slog.String("session_id", state.SessionID),
				slog.Int("files_touched", len(state.FilesTouched)),
				slog.Int("staged_files", len(opts.stagedFiles)),
				slog.Bool("result", result),
			)
			return result, nil
		}
		// PostCommit context: no staged files, but we have carry-forward files.
		// Return true and let the caller do the overlap check with committed files.
		logging.Debug(logCtx, "sessionHasNewContent: no transcript, carry-forward without staged files (post-commit context)",
			slog.String("session_id", state.SessionID),
			slog.Int("files_touched", len(state.FilesTouched)),
		)
		return true, nil
	}
	// No transcript and no FilesTouched - fall back to live transcript check
	logging.Debug(logCtx, "sessionHasNewContent: no transcript and no files touched, checking live transcript",
		slog.String("session_id", state.SessionID),
	)
	return s.sessionHasNewContentFromLiveTranscript(ctx, state, opts.stagedFiles)
}

// Check if there's new content to condense. Two cases:
// 1. Transcript has grown since last condensation (new prompts/responses)
// 2. FilesTouched has files not yet committed (carry-forward scenario)
//
// For PrepareCommitMsg context, we verify staged files overlap with session's files
// using content-aware matching to detect reverted files.
// For PostCommit context, stagedFiles is nil/empty (files already committed),
// so we return true and let the caller do the overlap check via filesOverlapWithContent.

// Fast path: compare blob size against stored size from last condensation.
// This avoids reading the full transcript content just to count items.
var hasTranscriptGrowth bool
switch {
case state.CheckpointTranscriptSize > 0:
	hasTranscriptGrowth = transcriptBlobSize > state.CheckpointTranscriptSize
case state.CheckpointTranscriptStart > 0:
	// Legacy session: condensed at least once (has line count) but no size tracking.
